def sha256_of(path):
    with open(path, "rb") as fh:
        return hashlib.sha256(fh.read()).hexdigest()


def run(cmd, cwd=None, allow_fail=False):
    print(f"[RUN] {' '.join(cmd)} (cwd={cwd or REPO_ROOT})")
    result = subprocess.run(cmd, cwd=cwd or REPO_ROOT, shell=False,
                             capture_output=True, text=True, timeout=900)
    if result.stdout:
        print(result.stdout)
    if result.stderr:
        print(result.stderr, file=sys.stderr)
    if result.returncode != 0 and not allow_fail:
        raise RuntimeError(f"コマンド失敗 (rc={result.returncode}): {' '.join(cmd)}")
    return result.returncode


def run_capture(cmd, cwd=None, allow_fail=False):
    print(f"[RUN] {' '.join(cmd)} (cwd={cwd or REPO_ROOT})")
    result = subprocess.run(cmd, cwd=cwd or REPO_ROOT, shell=False,
                             capture_output=True, text=True, timeout=900)
    if result.returncode != 0 and not allow_fail:
        if result.stdout:
            print(result.stdout)
        if result.stderr:
            print(result.stderr, file=sys.stderr)
        raise RuntimeError(f"コマンド失敗 (rc={result.returncode}): {' '.join(cmd)}")
    return result.returncode, result.stdout, result.stderr


def git(args):
    return run(["git"] + args, cwd=REPO_ROOT)


def compose(args, cwd=None, allow_fail=False, capture=False):
    cmd = ["docker", "compose", "-p", COMPOSE_PROJECT] + args
    if capture:
        return run_capture(cmd, cwd=cwd or REPO_ROOT, allow_fail=allow_fail)
    return run(cmd, cwd=cwd or REPO_ROOT, allow_fail=allow_fail)


def main():
    print("=== Gate #7a: フロントエンド共通コンポーネント整理 適用開始 ===\n")

    current_head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=REPO_ROOT).decode().strip()
    if current_head != EXPECTED_HEAD:
        print(f"[ABORT] HEAD不一致。期待={EXPECTED_HEAD} 実際={current_head}")
        sys.exit(1)
    print(f"[OK] HEAD一致確認: {current_head}")

    status = subprocess.check_output(
        ["git", "status", "--porcelain", "--untracked-files=no"], cwd=REPO_ROOT
    ).decode()
    if status.strip():
        print("[ABORT] 追跡済みファイルに未コミットの変更があります。先にcommit/stashしてください。")
        print(status)
        sys.exit(1)
    print("[OK] 作業ツリーはクリーン")

    for f in ALL_PREIMAGE_FILES:
        path = os.path.join(REPO_ROOT, f)
        if not os.path.exists(path):
            print(f"[ABORT] 対象ファイルが存在しません: {f}")
            sys.exit(1)
        actual = sha256_of(path)
        if actual != PREIMAGES[f]:
            print(f"[ABORT] preimage不一致: {f}\n        期待: {PREIMAGES[f]}\n        実際: {actual}")
            sys.exit(1)
    print(f"[OK] preimage一致確認 ({len(ALL_PREIMAGE_FILES)}ファイル)")

    backups = {}
    for f in ALL_PREIMAGE_FILES:
        path = os.path.join(REPO_ROOT, f)
        bak = path + ".gate7a.bak"
        shutil.copy2(path, bak)
        backups[f] = bak
    deleted_done = []

    try:
        for f in WRITE_TARGETS:
            path = os.path.join(REPO_ROOT, f)
            os.makedirs(os.path.dirname(path), exist_ok=True)
            content = base64.b64decode(CONTENT_B64[f])
            with open(path, "wb") as fh:
                fh.write(content)
            print(f"[WRITE] {f} ({len(content)} bytes)")

        for old, _new in MOVED_FILES:
            old_path = os.path.join(REPO_ROOT, old)
            if os.path.exists(old_path):
                os.remove(old_path)
                deleted_done.append(old)
                print(f"[REMOVE] {old} (moved)")

        for f in DELETED_FILES:
            path = os.path.join(REPO_ROOT, f)
            if os.path.exists(path):
                os.remove(path)
                deleted_done.append(f)
                print(f"[REMOVE] {f}")

        # 空になった frontend/hooks/ ディレクトリを削除
        stray_hooks = os.path.join(FRONTEND_DIR, "hooks")
        if os.path.isdir(stray_hooks) and not os.listdir(stray_hooks):
            os.rmdir(stray_hooks)
            print(f"[REMOVE DIR] {stray_hooks}")

        print("\n[GATE] npm install (package.json変更を反映) ...")
        run(["npm", "install"], cwd=FRONTEND_DIR)
        print("[OK] npm install 完了")

        print("\n[GATE] TypeScriptエラー件数の確認(0件化はGate #7bで継続、後退が無いことのみ確認) ...")
        rc, out, err = run_capture(["npx", "tsc", "--noEmit"], cwd=FRONTEND_DIR, allow_fail=True)
        error_count = out.count("error TS") + err.count("error TS")
        print(f"[INFO] 現在のTypeScriptエラー件数: {error_count} (適用前418件)")
        if error_count > 418:
            raise RuntimeError(f"エラー件数が悪化しました({error_count} > 418)。適用を中止します。")
        print("[OK] エラー件数は後退していません")

        print("\n[GATE] vite build (CIのblockingチェックと同一) ...")
        run(["npx", "vite", "build"], cwd=FRONTEND_DIR)
        print("[OK] vite build 成功")

        print("\n[GATE] frontendコンテナの再ビルド(bind mount無しのため必須) ...")
        compose(["build", "frontend"])
        compose(["up", "-d", "frontend"])
        import time as _time
        _time.sleep(5)
        rc, out, _ = compose(["ps", "--services", "--status", "running"], capture=True, allow_fail=True)
        if "frontend" not in out.split():
            raise RuntimeError("frontendコンテナの再起動後、running状態を確認できませんでした。"
                                "`docker compose -p travelcanvas logs frontend --tail 80` を確認してください。")
        print("[OK] frontendコンテナ再ビルド・起動確認 PASS")

        print("\n[OK] 全Gate PASS。commit/pushへ進みます。")

        for f in ALL_PREIMAGE_FILES:
            bak = backups[f]
            if os.path.exists(bak):
                os.remove(bak)

        git(["add", "-A"])

        commit_message = (
            "fix(frontend): consolidate common components, fix relative path depth bugs (Gate #7a)\n"
            "\n"
            f"TypeScript errors: 418 -> {error_count} (npx tsc --noEmit). Module resolution\n"
            "errors (TS2307) fully resolved; remaining errors are type-level issues\n"
            "(implicit any, property mismatches, etc.) tracked for Gate #7b.\n"
            "\n"
            "- Move Button/Card/Toast/Modal/Input.tsx into components/common/ to match\n"
            "  the existing convention (ErrorBoundary.tsx, MapView.tsx already lived there)\n"
            "- Fix 6 files under src/components/ that used '../common/X' (which actually\n"
            "  resolves to the nonexistent src/common/X) -> './common/X'\n"
            "- Fix 5 files that used '../../hooks/X' (one level too deep from\n"
            "  src/components/) -> '../hooks/X'; this had been silently resolving to a\n"
            "  stray duplicate frontend/hooks/ directory (byte-identical to src/hooks/,\n"
            "  confirmed via diff) instead of failing, which is now removed\n"
            "- Fix DayView.tsx ScheduleItem path, ShareModal.tsx services/api depth,\n"
            "  useRealtime.tsx WebSocket.ts casing\n"
            "- Unify common/LoadingSpinner.tsx to accept the 'sm'/'md'/'lg',\n"
            "  'small'/'large', and numeric-px size conventions already in use across\n"
            "  14 call sites, instead of rewriting each call site\n"
            "- Remove dead files with zero references from main.tsx's import chain:\n"
            "  src/App.2.tsx, src/pages/index.tsx (Next.js-era leftover), \n"
            "  src/components/planner/TimeProgress.tsx\n"
            "- Add missing @testing-library/user-event devDependency (already assumed\n"
            "  by vitest.config.ts and Button.test.tsx)\n"
            "\n"
            "Verified: npx vite build succeeds (same check as CI frontend job);\n"
            "frontend container rebuilt and confirmed running via docker compose.\n"
            "\n"
            "出典: Claude(claude.ai)セッション 2026-09-01, TravelCanvas Gate #7a"
        )
        git(["commit", "-m", commit_message])
        print("[OK] commit完了")

        git(["push", "origin", "HEAD"])
        print("[OK] push完了")

        new_head = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=REPO_ROOT).decode().strip()
        print(f"\n[DONE] Gate #7a 適用完了。新HEAD = {new_head}")

        self_path = os.path.abspath(__file__)
        if os.path.exists(self_path):
            os.remove(self_path)
            print(f"[CLEANUP] パッチ自身を削除しました: {self_path}")
        return

    except Exception as exc:
        print(f"\n[FAILURE] {exc}")
        print("[ROLLBACK] 変更対象ファイルのみをSHA-256一致までrestoreします(git reset --hard等は使用しません)。")
        for f in ALL_PREIMAGE_FILES:
            path = os.path.join(REPO_ROOT, f)
            bak = backups.get(f)
            if bak and os.path.exists(bak):
                os.makedirs(os.path.dirname(path), exist_ok=True)
                shutil.copy2(bak, path)
                os.remove(bak)
                restored_hash = sha256_of(path)
                match = "OK" if restored_hash == PREIMAGES[f] else "MISMATCH"
                print(f"  restore {f}: {match}")
        for old, new in MOVED_FILES:
            new_path = os.path.join(REPO_ROOT, new)
            if os.path.exists(new_path) and new not in [x for x, _ in []]:
                # newパスは元々存在しなかった場合のみ削除(preimage対象=oldなのでnewは常に新規)
                if new not in ALL_PREIMAGE_FILES:
                    os.remove(new_path)
                    print(f"  remove moved-target: {new}")
        print("[ROLLBACK] 完了。commit/pushは実行されていません。パッチ自身は調査用に残します。")
        sys.exit(1)


if __name__ == "__main__":
    main()
